import React, { useState } from 'react';
import { getRandomQuestion } from './services/dataService';

function App() {
  const [currentQuestion, setCurrentQuestion] = useState(getRandomQuestion());

  const getNewQuestion = () => {
    setCurrentQuestion(getRandomQuestion());
  };

  return (
    <div className="App">
      <h1>AP Economics Practice Game</h1>
      <div>
        <h2>当前问题：</h2>
        <p>政策: {currentQuestion.policy}</p>
        <p>变量: {currentQuestion.variable}</p>
        <p>正确答案: {currentQuestion.correctAnswer}</p>
        <p>解释: {currentQuestion.explanation}</p>
        <button onClick={getNewQuestion}>下一题</button>
      </div>
    </div>
  );
}

export default App;
